-- =============================================================================
-- Launch announcement, sent from the database.
--
-- GENERATED by scripts/gen-announce-sql.mjs from the same email module the Edge
-- Function uses. Do not hand-edit the copy below — regenerate it, or the two
-- senders drift apart.
--
-- Needs: pg_net (Database → Extensions) and the Resend key in Vault.
-- =============================================================================

create extension if not exists pg_net;

-- --- The key, stored once -----------------------------------------------------
-- Replace re_xxx with your Resend API key and run this line ONCE. It is stored
-- encrypted; nothing below ever prints it.
--
--   select vault.create_secret('re_xxx', 'resend_api_key');
--
-- Already stored one and want to change it:
--   select vault.update_secret(id, 're_new') from vault.secrets where name = 'resend_api_key';

-- --- The sender ---------------------------------------------------------------

create or replace function public.announce_launch(
  p_limit    int  default 50,
  p_test_to  text default null,
  p_from     text default 'Pocket Athlete <hello@pocketathlete.com>'
)
returns table (emailed int, remaining int, note text)
language plpgsql
security definer
set search_path = public, pg_temp
as $fn$
declare
  v_key   text;
  v_html  text := $mail$<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>Pocket Athlete is live — your spot is ready 🔥</title></head>
<body style="margin:0;padding:0;background:#0b0f0d;">
<div style="display:none;max-height:0;overflow:hidden;opacity:0;">Your position. Your plan. Your numbers. It's open.</div>
